// Audit logging system
class AuditLogger {
public:
    static AuditLogger& instance() {
        static AuditLogger logger;
        return logger;
    }
    void log(const std::string& event, const std::string& detail) {
        std::ofstream out("audit.log", std::ios::app);
        out << "[AUDIT] " << event << ": " << detail << std::endl;
    }
private:
    AuditLogger() = default;
};

// Tensor type enumeration
enum class TensorDType : uint8_t {
    FLOAT32 = 0,
    FLOAT64 = 1,
    INT32 = 2,
    INT64 = 3,
    UINT8 = 4
};

// Base tensor storage - type-erased
struct TensorStorage {
    void* data;
    size_t num_elements;
    TensorDType dtype;
    size_t refcount;

    TensorStorage(void* d, size_t n, TensorDType t)
        : data(d), num_elements(n), dtype(t), refcount(1) {}

    ~TensorStorage() {
        if (data) free(data);
    }

    size_t element_size() const {
        switch (dtype) {
            case TensorDType::FLOAT32: return 4;
            case TensorDType::FLOAT64: return 8;
            case TensorDType::INT32: return 4;
            case TensorDType::INT64: return 8;
            case TensorDType::UINT8: return 1;
            default: return 0;
        }
    }

    size_t total_bytes() const {
        return num_elements * element_size();
    }
};

// Model layer abstraction
class InferenceLayer {
public:
    virtual ~InferenceLayer() = default;
    virtual TensorStorage* forward(TensorStorage* input) = 0;
    virtual std::string name() const = 0;
};

// Quantization layer - converts float32 to uint8 for efficiency
class QuantizationLayer : public InferenceLayer {
    float scale_;
    int32_t zero_point_;
public:
    QuantizationLayer(float scale, int32_t zp) : scale_(scale), zero_point_(zp) {}

    TensorStorage* forward(TensorStorage* input) override {
        AuditLogger::instance().log("QuantizationLayer",
            "Processing " + std::to_string(input->num_elements) + " elements");

        // Allocate output as UINT8
        size_t n = input->num_elements;
        uint8_t* out_data = (uint8_t*)malloc(n * sizeof(uint8_t));
        if (!out_data) {
            AuditLogger::instance().log("Error", "QuantizationLayer allocation failed");
            return nullptr;
        }

        if (input->dtype == TensorDType::FLOAT32) {
            float* in = static_cast<float*>(input->data);
            for (size_t i = 0; i < n; i++) {
                int32_t quantized = static_cast<int32_t>(in[i] / scale_) + zero_point_;
                out_data[i] = static_cast<uint8_t>(std::max(0, std::min(255, quantized)));
            }
        }

        return new TensorStorage(out_data, n, TensorDType::UINT8);
    }

    std::string name() const override { return "Quantize"; }
};

// Dequantization layer - converts back
class DequantizationLayer : public InferenceLayer {
    float scale_;
    int32_t zero_point_;
public:
    DequantizationLayer(float scale, int32_t zp) : scale_(scale), zero_point_(zp) {}

    TensorStorage* forward(TensorStorage* input) override {
        AuditLogger::instance().log("DequantizationLayer",
            "Processing " + std::to_string(input->num_elements) + " elements");

        size_t n = input->num_elements;
        float* out_data = (float*)malloc(n * sizeof(float));
        if (!out_data) {
            AuditLogger::instance().log("Error", "DequantizationLayer allocation failed");
            return nullptr;
        }

        // Critical: uses num_elements from input tensor metadata
        // but interprets data according to declared dtype
        uint8_t* in = static_cast<uint8_t*>(input->data);
        for (size_t i = 0; i < n; i++) {
            out_data[i] = (static_cast<float>(in[i]) - zero_point_) * scale_;
        }

        return new TensorStorage(out_data, n, TensorDType::FLOAT32);
    }

    std::string name() const override { return "Dequantize"; }
};

// Activation layer that operates on float32
class ReLULayer : public InferenceLayer {
public:
    TensorStorage* forward(TensorStorage* input) override {
        AuditLogger::instance().log("ReLULayer",
            "dtype=" + std::to_string(static_cast<int>(input->dtype)));

        // Type safety check - only process correct dtype
        if (input->dtype != TensorDType::FLOAT32) {
            AuditLogger::instance().log("Error", "ReLU requires FLOAT32 input");
            // Pass through with type preservation
            size_t bytes = input->total_bytes();
            void* out_data = malloc(bytes);
            if (!out_data) {
                AuditLogger::instance().log("Error", "ReLU passthrough allocation failed");
                return nullptr;
            }
            memcpy(out_data, input->data, bytes);
            return new TensorStorage(out_data, input->num_elements, input->dtype);
        }

        size_t n = input->num_elements;
        float* out_data = (float*)malloc(n * sizeof(float));
        if (!out_data) {
            AuditLogger::instance().log("Error", "ReLU allocation failed");
            return nullptr;
        }
        float* in = static_cast<float*>(input->data);
        for (size_t i = 0; i < n; i++) {
            out_data[i] = in[i] > 0.0f ? in[i] : 0.0f;
        }
        return new TensorStorage(out_data, n, TensorDType::FLOAT32);
    }

    std::string name() const override { return "ReLU"; }
};

// Pipeline executor with caching optimization
class InferencePipeline {
    std::vector<std::unique_ptr<InferenceLayer>> layers_;
    std::unordered_map<std::string, TensorStorage*> cache_;
    bool use_quantized_cache_;

public:
    InferencePipeline(bool quantized_cache = false)
        : use_quantized_cache_(quantized_cache) {}

    void add_layer(std::unique_ptr<InferenceLayer> layer) {
        layers_.push_back(std::move(layer));
    }

    TensorStorage* run(TensorStorage* input, const std::string& request_id) {
        AuditLogger::instance().log("Pipeline", "Starting inference: " + request_id);

        TensorStorage* current = input;
        TensorStorage* prev = nullptr;

        for (size_t i = 0; i < layers_.size(); i++) {
            auto cache_key = request_id + "_L" + std::to_string(i);

            // Check cache - reuse previous computation
            if (cache_.count(cache_key)) {
                AuditLogger::instance().log("Cache", "Hit for " + cache_key);
                // Validate cached dtype matches what the next layer expects
                TensorStorage* cached = cache_[cache_key];
                current = cached;
                continue;
            }

            prev = current;
            current = layers_[i]->forward(current);
            if (!current) {
                AuditLogger::instance().log("Error", "Layer forward returned null");
                if (prev != input && !use_quantized_cache_) {
                    delete prev;
                }
                return nullptr;
            }

            // Cache intermediate results
            if (use_quantized_cache_) {
                cache_[cache_key] = current;
            }

            // Free intermediate (but not input or cached)
            if (prev != input && !use_quantized_cache_) {
                delete prev;
            }
        }

        AuditLogger::instance().log("Pipeline", "Completed: " + request_id);
        return current;
    }

    // Warm cache with pre-quantized data for repeated inference
    void warm_cache(const std::string& request_id, size_t layer_idx,
                    void* data, size_t num_elements, TensorDType dtype) {
        auto cache_key = request_id + "_L" + std::to_string(layer_idx);
        size_t elem_sz = 0;
        switch (dtype) {
            case TensorDType::FLOAT32: elem_sz = 4; break;
            case TensorDType::FLOAT64: elem_sz = 8; break;
            case TensorDType::INT32: elem_sz = 4; break;
            case TensorDType::INT64: elem_sz = 8; break;
            case TensorDType::UINT8: elem_sz = 1; break;
        }
        if (elem_sz == 0) {
            AuditLogger::instance().log("Error", "warm_cache invalid dtype");
            return;
        }
        // Guard against integer overflow in allocation size computation.
        if (num_elements != 0 &&
            num_elements > std::numeric_limits<size_t>::max() / elem_sz) {
            AuditLogger::instance().log("Error", "warm_cache size overflow");
            return;
        }
        size_t total = num_elements * elem_sz;
        void* copy = malloc(total);
        if (!copy) {
            AuditLogger::instance().log("Error", "warm_cache allocation failed");
            return;
        }
        memcpy(copy, data, total);
        cache_[cache_key] = new TensorStorage(copy, num_elements, dtype);
        AuditLogger::instance().log("CacheWarm",
            "Warmed " + cache_key + " with dtype=" + std::to_string((int)dtype));
    }

    ~InferencePipeline() {
        for (auto& [k, v] : cache_) delete v;
    }
};

// Server request handler
struct InferenceRequest {
    std::string model_id;
    std::string request_id;
    std::vector<float> input_data;
    bool use_cache;
};

class InferenceServer {
    std::unordered_map<std::string, std::unique_ptr<InferencePipeline>> pipelines_;

public:
    void register_model(const std::string& model_id, bool quantized) {
        auto pipeline = std::make_unique<InferencePipeline>(quantized);
        pipeline->add_layer(std::make_unique<QuantizationLayer>(0.05f, 128));
        pipeline->add_layer(std::make_unique<ReLULayer>());
        pipeline->add_layer(std::make_unique<DequantizationLayer>(0.05f, 128));
        pipelines_[model_id] = std::move(pipeline);
    }

    std::vector<float> infer(const InferenceRequest& req) {
        AuditLogger::instance().log("Server",
            "Request " + req.request_id + " for model " + req.model_id);

        auto it = pipelines_.find(req.model_id);
        if (it == pipelines_.end()) {
            AuditLogger::instance().log("Error", "Model not found: " + req.model_id);
            return {};
        }

        // Create input tensor
        size_t n = req.input_data.size();
        float* input_copy = (float*)malloc(n * sizeof(float));
        if (!input_copy) {
            AuditLogger::instance().log("Error", "Input allocation failed");
            return {};
        }
        memcpy(input_copy, req.input_data.data(), n * sizeof(float));
        auto* input_tensor = new TensorStorage(input_copy, n, TensorDType::FLOAT32);

        // Run pipeline
        TensorStorage* output = it->second->run(input_tensor, req.request_id);
        if (!output) {
            AuditLogger::instance().log("Error", "Pipeline returned null output");
            return {};
        }

        // Extract results - verify output dtype before interpreting
        std::vector<float> results(output->num_elements);
        if (output->dtype == TensorDType::FLOAT32) {
            memcpy(results.data(), output->data, output->num_elements * sizeof(float));
        } else {
            AuditLogger::instance().log("Error", "Unexpected output dtype");
            results.clear();
        }

        AuditLogger::instance().log("Server", "Completed " + req.request_id);
        return results;
    }
};

int main() {
    InferenceServer server;
    // Register model with quantized caching enabled
    server.register_model("resnet50", true);

    InferenceRequest req;
    req.model_id = "resnet50";
    req.request_id = "req_001";
    req.input_data = {1.0f, -2.0f, 3.5f, 0.0f, -1.5f, 4.2f, 2.1f, -0.5f};
    req.use_cache = true;

    auto results = server.infer(req);

    std::cout << "Results: ";
    for (float v : results) std::cout << v << " ";
    std::cout << std::endl;

    // Second request reuses cache - safe due to dtype checks
    req.request_id = "req_001";  // same ID to hit cache
    auto results2 = server.infer(req);

    std::cout << "Cached Results: ";
    for (float v : results2) std::cout << v << " ";
    std::cout << std::endl;

    return 0;
}
